const AUTH_KEY='finbase-auth-session';
function showLogin(){document.body.classList.add('auth-required');$('loginScreen').hidden=false;$('loginError').hidden=true;setTimeout(()=>$('loginName').focus(),50)}
function hasActiveSession(){try{const session=JSON.parse(localStorage.getItem(AUTH_KEY)||'null'),account=USERS[session?.user];if(!account||session.expiresAt<=Date.now())return false;currentUser.name=session.user;currentUser.role=account.role;return true}catch{return false}}
function setSession(user){const account=USERS[user];currentUser.name=user;currentUser.role=account.role;localStorage.setItem(AUTH_KEY,JSON.stringify({user,expiresAt:Date.now()+7*24*60*60*1000}))}
function unlock(){document.body.classList.remove('auth-required');$('loginScreen').hidden=true;$('loginForm').reset()}
if(!hasActiveSession())showLogin();
$('loginForm').onsubmit=e=>{e.preventDefault();const user=$('loginName').value.trim(),password=$('loginPassword').value,account=USERS[user];if(account&&password===account.password){setSession(user);unlock();log('Авторизація в системі','Успішний вхід');save();render()}else{$('loginError').hidden=false;$('loginPassword').select()}};
$('togglePassword').onclick=()=>{const input=$('loginPassword'),shown=input.type==='text';input.type=shown?'password':'text';$('togglePassword').textContent=shown?'◉':'◉'};
$('logoutButton').onclick=()=>{if(confirm('Вийти з облікового запису?')){localStorage.removeItem(AUTH_KEY);showLogin()}};
const money=v=>Number(v||0).toLocaleString('uk-UA',{minimumFractionDigits:2,maximumFractionDigits:2});
const {roundMoney,valueOf,getSignedAmount,requiresFundsCheck,getRefundType,accountAvailabilityDecision,frozen:accountFrozen,available:accountAvailable}=window.FinbaseAccounting;
const newId=()=>globalThis.crypto?.randomUUID?.()||`tx-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const icon=t=>['income','contribution','refund_in','opening_balance'].includes(t)?'<svg><use href="#i-arrow-down"/></svg>':['refund_out','contribution_return'].includes(t)?'<svg><use href="#i-return"/></svg>':t==='payout'?'<svg><use href="#i-wallet"/></svg>':'<svg><use href="#i-arrow-up"/></svg>';
const save=()=>{localStorage.setItem(STORAGE,JSON.stringify(transactions));localStorage.setItem('finbase-journal',JSON.stringify(journal));localStorage.setItem('finbase-partner-shares',JSON.stringify(manualShares));localStorage.setItem('finbase-closed-periods',JSON.stringify(closedPeriods));localStorage.setItem(DISTRIBUTION_SETTINGS_KEY,JSON.stringify(distributionSettings));localStorage.setItem(DISTRIBUTIONS_KEY,JSON.stringify(distributions));localStorage.setItem(PLANNED_PAYMENTS_KEY,JSON.stringify(plannedPayments));localStorage.setItem(PLANNED_SETTINGS_KEY,JSON.stringify(plannedSettings));localStorage.setItem(PLANNED_TEMPLATES_KEY,JSON.stringify(plannedTemplates));localStorage.setItem(TAX_RULES_KEY,JSON.stringify(taxRules));if(window.financeStore?.enabled)return window.financeStore.save({transactions,journal,closedPeriods,manualShares,distributionSettings,distributions,plannedPayments,plannedSettings,plannedTemplates,taxRules}).catch(error=>{console.error('Не вдалося зберегти зміни у Firebase Realtime Database.',error);return false});return Promise.resolve(true)};
const log=(action,details)=>journal.unshift({at:new Date().toISOString(),user:currentUser.name,action,details});
const isTransfer=t=>Boolean(t.transferId||t.isTransfer);
const isDeleted=t=>t.isDeleted===true;
const getActiveTransactions=(list=transactions)=>list.filter(t=>!isDeleted(t));
const periodFor=date=>window.FinbasePeriods.findClosedPeriodForDate(closedPeriods,date);
const isClosed=date=>Boolean(periodFor(date));
const periodName=p=>p?`${p.start||p.from} — ${p.end||p.to}`:'';
function assertDateOpen(isoDate,actionName='Зміна'){const period=periodFor(isoDate);if(!period)return true;throw new Error(`Дата ${isoDate} належить закритому періоду ${periodName(period)}. Виправлення зробіть новою операцією в поточному періоді з коментарем “Коригування за ${periodName(period)}”`)}
function periodTools(){return window.FinbasePeriods.createPeriodTools({transactions,accounts:Object.keys(accounts),owners,signedAmount:getSignedAmount})}
function getBalanceAt(account,isoDate){return periodTools().getBalanceAt(account,isoDate)}
function getMinBalanceInRange(account,startIso,endIso){return periodTools().getMinBalanceInRange(account,startIso,endIso)}
function computePeriodReport(startIso,endIso){return periodTools().computePeriodReport(startIso,endIso)}
function computeCumulativeUndistributed(endIso){return periodTools().computeCumulativeUndistributed(endIso)}
function computePartnerPositions(endIso){return periodTools().computePartnerPositions(endIso)}
function findClosedPeriodForDate(isoDate){return periodFor(isoDate)}
function findBrokenTransfers(){return periodTools().findBrokenTransfers()}
const dateKey=t=>`${t.isoDate||''}T${t.time||String(t.date||'').split(', ')[1]||'00:00'}|${t.transferOrder||0}|${t.id}`;
function balanceTimeline(list=transactions){const balances=Object.fromEntries(Object.keys(accounts).map(a=>[a,0]));return getActiveTransactions(list).slice().sort((a,b)=>dateKey(a).localeCompare(dateKey(b))).map(t=>{balances[t.account]=roundMoney((balances[t.account]||0)+getSignedAmount(t));return{t,balances:{...balances}}})}
function firstNegative(list=transactions,from=''){for(const row of balanceTimeline(list)){if(from&&row.t.isoDate<from)continue;for(const [account,balance] of Object.entries(row.balances))if(balance<0)return{account,date:row.t.isoDate,balance}}return null}
function validateBalances(candidate,from){const bad=firstNegative(candidate,from);return bad?`Операція створює від’ємний залишок на рахунку «${bad.account}» з ${bad.date}: ₴ ${money(bad.balance)}.`:''}
function activeRefundsFor(id,exceptId){return getActiveTransactions().filter(t=>t.originalId===id&&String(t.id)!==String(exceptId)&&['refund_in','refund_out'].includes(t.type))}
function validateRefund(t,exceptId){if(!t.originalId)return'';const original=getActiveTransactions().find(x=>String(x.id)===String(t.originalId));const expected=t.type==='refund_out'?'income':'expense';if(!original||original.type!==expected)return'Оригінальна операція не знайдена або скасована.';const total=roundMoney(activeRefundsFor(original.id,exceptId).reduce((s,x)=>s+valueOf(x),0)+valueOf(t));return total>valueOf(original)?`Сума повернень (${money(total)}) перевищує суму оригіналу (${money(valueOf(original))}).`:''}
const accountImage=account=>account==='ФОП новапей'?'image/novapay.png':(['ФОП моно','Біла карта','Резервний фонд'].includes(account)?'image/mono.png':'');
const accountLogo=(account,className='account-logo-img')=>{const source=accountImage(account);return source?`<img class="${className}" src="${source}" alt="${account}">`:''};

// Безпечна одноразова міграція: старі id лишаються чинними, старе refund стає refund_in.
function migrateState(){let refunds=0,changed=false;transactions=transactions.map(t=>{const next={...t,value:valueOf(t)};if(t.transferId){next.isTransfer=true;next.transferOrder=t.type==='expense'?1:2}if(t.type==='refund'){next.type='refund_in';next.migratedLegacyRefund=true;refunds++}if(!t.isoDate&&t.date){const d=new Date(t.date);if(!Number.isNaN(d.valueOf()))next.isoDate=d.toISOString().slice(0,10)}if(JSON.stringify(next)!==JSON.stringify(t))changed=true;return next});distributions=distributions.map(item=>{const next={reserve:0,reserveTarget:0,reserveShortfall:0,reserveSource:'',loanRepayments:Object.fromEntries(owners.map(owner=>[owner,0])),...item};if(JSON.stringify(next)!==JSON.stringify(item))changed=true;return next});const planned=window.FinbasePlannedPayments.migrateState({plannedPayments,plannedSettings});if(JSON.stringify(planned.plannedPayments)!==JSON.stringify(plannedPayments)||JSON.stringify(planned.plannedSettings)!==JSON.stringify(plannedSettings))changed=true;plannedPayments=planned.plannedPayments;plannedSettings=planned.plannedSettings;const version=Number(localStorage.getItem('finbase-data-version')||0);if(version<DATA_VERSION){if(refunds)log('Міграція даних',`${refunds} старих повернень змінено на «Повернення від постачальника». Перевірте напрямок міграційних записів вручну.`);log('Міграція даних',`Версію даних оновлено до ${DATA_VERSION}; додано планові платежі та їх налаштування.`);localStorage.setItem('finbase-data-version',String(DATA_VERSION));changed=true}if(changed)save()}

window.financePlannedPayments={
  get payments(){return plannedPayments.map(item=>({...item}))},
  get settings(){return{...plannedSettings}},
  remainingAmount:window.FinbasePlannedPayments.remainingAmount,
  create(input){const payment=window.FinbasePlannedPayments.createPayment({...input,id:input.id||newId()},{createdBy:currentUser.name});plannedPayments.unshift(payment);log('Створено плановий платіж',`${payment.name}, ₴ ${money(payment.amount)}`);save();return payment},
  updateSettings(patch){const previous=plannedSettings;plannedSettings=window.FinbasePlannedPayments.updateSettings(previous,patch,currentUser.role);log('Змінено налаштування планових платежів',`${JSON.stringify(previous)} → ${JSON.stringify(plannedSettings)}`);save();return plannedSettings},
  update(id,patch,comment){if(String(comment||'').trim().length<5)throw new Error('Коментар має містити щонайменше 5 символів.');const index=plannedPayments.findIndex(item=>String(item.id)===String(id));if(index<0)throw new Error('Плановий платіж не знайдено.');const previous=plannedPayments[index],next=window.FinbasePlannedPayments.createPayment({...previous,...patch});plannedPayments[index]=next;log('Змінено плановий платіж',`${JSON.stringify(previous)} → ${JSON.stringify(next)}; коментар: ${comment}`);save();return next},
  cancel(id,comment){return this.update(id,{status:'cancelled'},comment)}
};
{const migratedPeriods=window.FinbasePeriods.migratePeriods(closedPeriods);if(JSON.stringify(migratedPeriods)!==JSON.stringify(closedPeriods)){closedPeriods.splice(0,closedPeriods.length,...migratedPeriods);save()}}
migrateState();

function balanceFor(account,list=transactions,to=''){return roundMoney(getActiveTransactions(list).filter(t=>t.account===account&&(!to||t.isoDate<=to)).reduce((sum,t)=>sum+getSignedAmount(t),0))}
let availabilityCheckContext=null;
function assertAccountAvailable(account,amount,txType,plannedPaymentId){
 const context=availabilityCheckContext||{},decision=accountAvailabilityDecision(account,amount,txType,plannedPaymentId,{balance:context.balance??balanceFor(account),plannedPayments:context.plannedPayments||plannedPayments,plannedSettings,today:isoLocal(new Date())});
 if(txType==='payout'){const planned=plannedFinancials(),limit=roundMoney(planned.freeMoney+Number(context.payoutBaseAdjustment||0));if(planned.deficit>0||amount>limit){decision.ok=false;decision.available=limit;decision.shortfall=Math.max(0,roundMoney(amount-limit))}}
 if(decision.ok)return decision;
 log('Заблоковано: недостатньо доступних коштів',`${account}, ₴ ${money(amount)}`);save();
 const error=new Error(`Недостатньо доступних коштів на рахунку «${account}». Баланс: ${money(decision.balance)} грн, заморожено: ${money(decision.frozen)} грн, доступно: ${money(decision.available)} грн. Сума операції: ${money(decision.amount)} грн, не вистачає: ${money(decision.shortfall)} грн.`);error.code='ACCOUNT_AVAILABLE';error.details=decision;throw error
}
window.assertAccountAvailable=assertAccountAvailable;
function updatePlannedPaidAmount(id,delta){if(!id||!delta)return;plannedPayments=plannedPayments.map(payment=>{if(String(payment.id)!==String(id))return payment;const paidAmount=Math.max(0,Math.min(Number(payment.amount),roundMoney(Number(payment.paidAmount||0)+delta)));return{...payment,paidAmount,status:paidAmount>=Number(payment.amount)?'paid':'planned'}})}
function syncPlannedPaymentForTransactionChange(oldTx,newTx){if(oldTx?.type==='expense'&&oldTx.plannedPaymentId&&!oldTx.isDeleted)updatePlannedPaidAmount(oldTx.plannedPaymentId,-valueOf(oldTx));if(newTx?.type==='expense'&&newTx.plannedPaymentId&&!newTx.isDeleted)updatePlannedPaidAmount(newTx.plannedPaymentId,valueOf(newTx))}
function showAvailabilityBlocked(error,expense=false){const box=$('transactionError');box.hidden=false;box.innerHTML=`${error.message}<div class="period-row-actions"><button type="button" class="btn secondary" data-view-planned>Переглянути планові платежі</button>${expense?'<button type="button" class="btn secondary" data-link-planned>Прив’язати до планового платежу</button>':''}</div>`;box.querySelector('[data-view-planned]').onclick=()=>window.dispatchEvent(new CustomEvent('finbase:show-planned-payments'));box.querySelector('[data-link-planned]')?.addEventListener('click',()=>{$('plannedPaymentField').hidden=false;$('plannedPaymentId').focus()})}
function operatingIncome(list=transactions){return roundMoney(getActiveTransactions(list).filter(t=>!isTransfer(t)&&['income','refund_out'].includes(t.type)).reduce((s,t)=>s+getSignedAmount(t),0))}
function operatingExpense(list=transactions){return roundMoney(-getActiveTransactions(list).filter(t=>!isTransfer(t)&&['expense','refund_in'].includes(t.type)).reduce((s,t)=>s+getSignedAmount(t),0))}
function payouts(list=transactions){return roundMoney(-getActiveTransactions(list).filter(t=>t.type==='payout').reduce((s,t)=>s+getSignedAmount(t),0))}
function visibleText(t){return[t.isoDate,t.date,valueOf(t),t.cat,t.party,t.account,t.desc].join(' ').toLowerCase()}
function filteredRows(){const q=$('searchInput').value.toLowerCase();return transactions.filter(t=>{const kind=activeFilter==='all'||t.type===activeFilter||(activeFilter==='income'&&['income','refund_out'].includes(t.type)&&!isTransfer(t))||(activeFilter==='expense'&&['expense','refund_in'].includes(t.type)&&!isTransfer(t));return kind&&visibleText(t).includes(q)&&(!dateFrom||(t.isoDate||'')>=dateFrom)&&(!dateTo||(t.isoDate||'')<=dateTo)}).sort((a,b)=>dateKey(b).localeCompare(dateKey(a)))}
function renderStats(visible){
 const inc=operatingIncome(),exp=operatingExpense(),profit=inc-exp,cash=Object.keys(accounts).reduce((s,a)=>s+balanceFor(a),0);
 const active=getActiveTransactions();$('balanceMetric').textContent=`₴ ${money(cash)}`;$('incomeMetric').textContent=`₴ ${money(inc)}`;$('expenseMetric').textContent=`₴ ${money(exp)}`;$('profitMetric').textContent=`₴ ${money(profit)}`;$('balanceCaption').textContent=active.length?`${active.length} операцій в обліку`:'Операцій ще немає';
 $('allCount').textContent=active.length;$('incomeCount').textContent=active.filter(t=>['income','refund_out'].includes(t.type)&&!isTransfer(t)).length;$('expenseCount').textContent=active.filter(t=>['expense','refund_in'].includes(t.type)&&!isTransfer(t)).length;
 const vi=operatingIncome(visible),ve=operatingExpense(visible),vp=payouts(visible),cashResult=visible.filter(t=>!isDeleted(t)).reduce((s,t)=>s+getSignedAmount(t),0);
 $('footerCount').textContent=`${visible.filter(t=>!isDeleted(t)).length} активних операцій`;$('footerIncome').textContent=`+${money(vi)}`;$('footerExpense').textContent=`−${money(ve+vp)}`;$('footerResult').textContent=`${cashResult>=0?'+':'−'}${money(Math.abs(cashResult))}`;$('shownCount').textContent=visible.length;$('totalCount').textContent=transactions.filter(t=>!isDeleted(t)).length;
}
function render(){const visible=filteredRows();$('transactionRows').innerHTML=visible.length?visible.map(t=>`<tr class="${isDeleted(t)?'voided-row':''}"><td><input type="checkbox" aria-label="Обрати" ${isDeleted(t)?'disabled':''}></td><td class="date">${t.date}</td><td><div class="description"><span class="trans-icon ${t.type}">${icon(t.type)}</span><span class="description-text" title="${t.desc}">${t.desc}</span></div></td><td><span class="category" style="--tag:${t.color||'#9aa'}">${t.cat||'—'}</span></td><td>${t.party||'—'}</td><td><span class="account has-logo">${accountLogo(t.account,'transaction-account-logo')}${t.account}</span></td><td class="amount ${t.type}">${getSignedAmount(t)<0?'− ':'+ '}${money(valueOf(t))}</td><td><span class="status ${isDeleted(t)?'cancelled':''}">${isDeleted(t)?'Скасовано':(t.status||'Проведено')}</span></td><td class="row-actions">${isDeleted(t)?`<button class="row-menu permanent-delete" data-permanent-delete="${t.id}" title="Видалити назавжди" aria-label="Видалити назавжди"><svg><use href="#i-trash"/></svg></button>`:`<button class="row-menu" data-edit="${t.id}" title="Редагувати" aria-label="Редагувати"><svg><use href="#i-edit"/></svg></button><button class="row-menu delete-payment" data-delete="${t.id}" title="Скасувати платіж" aria-label="Скасувати платіж"><svg><use href="#i-x"/></svg></button>`}</td></tr>`).join(''):'<tr class="empty-row"><td colspan="9"><strong>Транзакцій поки немає</strong>Додайте першу транзакцію, щоб розпочати облік</td></tr>';renderStats(visible);renderAccounts();renderReport();renderStatistics();renderJournal()}

function renderAccounts(){const now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`,data=Object.keys(accounts).map(name=>{const list=transactions.filter(t=>t.account===name&&!isDeleted(t)),inc=list.filter(t=>getSignedAmount(t)>0).reduce((s,t)=>s+getSignedAmount(t),0),out=-list.filter(t=>getSignedAmount(t)<0).reduce((s,t)=>s+getSignedAmount(t),0),balance=roundMoney(inc-out),planned=accountFrozen(name,plannedPayments,plannedSettings,today),available=accountAvailable(name,balance,plannedPayments,plannedSettings,today);return{name,color:accounts[name],operations:list.length,income:inc,out,balance,planned,available}});const total=data.reduce((s,a)=>s+a.balance,0);$('accountCards').innerHTML=data.map(a=>`<article class="account-balance-card" style="--account-color:${a.color}"><div class="account-card-top">${accountLogo(a.name)}<span class="account-card-name">${a.name}</span>${a.name==='Резервний фонд'?'<span class="account-badge">Віртуальний</span>':''}</div><small>Поточний баланс</small><strong class="${a.balance<0?'negative-balance':''}">₴ ${money(a.balance)}</strong><div class="account-reserve-summary"><span><em>Планові платежі</em><b class="planned-reserved">− ₴ ${money(a.planned)}</b></span><span><em>Доступно для операцій</em><b class="account-available ${a.available<0?'low':''}">₴ ${money(Math.max(0,a.available))}</b></span></div><div class="account-meta"><span>Надходження <b>+${money(a.income)}</b></span><span>Списання <b>−${money(a.out)}</b></span></div></article>`).join('');$('accountsRows').innerHTML=data.map(a=>`<tr><td><span class="account-name-cell">${accountLogo(a.name,'account-table-logo')}<span>${a.name}${a.name==='Резервний фонд'?'<small class="account-badge">Віртуальний</small>':''}</span></span></td><td>${a.operations}</td><td class="amount income">+${money(a.income)}</td><td class="amount" style="color:var(--red)">−${money(a.out)}</td><td class="amount ${a.balance<0?'expense':'income'}">${a.balance<0?'−':'+'}${money(Math.abs(a.balance))}</td></tr>`).join('');$('accountsTotalOperations').textContent=data.reduce((s,a)=>s+a.operations,0);$('accountsTotalIncome').textContent=`+${money(data.reduce((s,a)=>s+a.income,0))}`;$('accountsTotalExpense').textContent=`−${money(data.reduce((s,a)=>s+a.out,0))}`;$('accountsTotalBalance').textContent=`${total<0?'−':'+'}${money(Math.abs(total))}`;$('accountsUpdated').textContent=`Оновлено: ${new Date().toLocaleTimeString('uk-UA',{hour:'2-digit',minute:'2-digit'})}`}
