// Синхронізація даних при оновленні в базі Firebase Realtime Database
window.onCloudStateChange = cloud => {
  if (!cloud) return;
  if (Array.isArray(cloud.transactions)) {
    transactions = cloud.transactions;
    localStorage.setItem(STORAGE, JSON.stringify(transactions));
  }
  if (Array.isArray(cloud.journal)) {
    journal = cloud.journal;
    localStorage.setItem('finbase-journal', JSON.stringify(journal));
  }
  if (cloud.manualShares) {
    manualShares = cloud.manualShares;
    localStorage.setItem('finbase-partner-shares', JSON.stringify(manualShares));
  }
  if (cloud.distributionSettings) {
    distributionSettings = {...defaultDistributionSettings, ...cloud.distributionSettings};
    localStorage.setItem(DISTRIBUTION_SETTINGS_KEY, JSON.stringify(distributionSettings));
  }
  if (Array.isArray(cloud.distributions)) {
    distributions = cloud.distributions;
    localStorage.setItem(DISTRIBUTIONS_KEY, JSON.stringify(distributions));
  }
  plannedPayments = Array.isArray(cloud.plannedPayments) ? cloud.plannedPayments : [];
  plannedTemplates = Array.isArray(cloud.plannedTemplates) ? cloud.plannedTemplates : [];
  taxRules = Array.isArray(cloud.taxRules) ? cloud.taxRules : [];
  plannedSettings = window.FinbasePlannedPayments.normalizeSettings(cloud.plannedSettings || {});
  localStorage.setItem(PLANNED_PAYMENTS_KEY, JSON.stringify(plannedPayments));
  localStorage.setItem(PLANNED_SETTINGS_KEY, JSON.stringify(plannedSettings));
  localStorage.setItem(PLANNED_TEMPLATES_KEY, JSON.stringify(plannedTemplates));
  localStorage.setItem(TAX_RULES_KEY, JSON.stringify(taxRules));
  if (cloud.closedPeriods == null || Array.isArray(cloud.closedPeriods)) {
    closedPeriods.splice(0, closedPeriods.length, ...(cloud.closedPeriods || []));
    closedPeriods.splice(0,closedPeriods.length,...window.FinbasePeriods.migratePeriods(closedPeriods));
    localStorage.setItem('finbase-closed-periods', JSON.stringify(closedPeriods));
  }
  migrateState();
  migrationPanel();
  render();
};

// Після ініціалізації Firebase база стає спільним джерелом даних
window.addEventListener('load', async () => {
  const cloud = await window.financeStore?.ready;
  if (!window.financeStore?.enabled) return;
  if (cloud) {
    window.onCloudStateChange(cloud);
  } else {
    // Нова база: зберігаємо початковий стан лише якщо в хмарі ще немає запису.
    await save();
  }
  migrationPanel();
  render();
});

