$('closedPeriodRows').onclick=e=>{const snapshotIndex=e.target.dataset.snapshot,reopenIndex=e.target.dataset.reopen;if(snapshotIndex===undefined&&reopenIndex===undefined)return;const p=closedPeriods[Number(snapshotIndex??reopenIndex)];if(!p)return;if(snapshotIndex!==undefined){const current=snapshotFor(p.from,p.to),same=JSON.stringify(current)===JSON.stringify(p.snapshot);alert(`${periodName(p)}\n${same?'✔ Знімок відповідає транзакціям':'⚠ Показники відрізняються від знімка'}\n\n${JSON.stringify(p.snapshot,null,2)}`);return}if(currentUser.role!=='Власник')return alert('Відкрити період може лише власник.');const latest=closedPeriods.filter(x=>!x.reopenedAt).sort((a,b)=>b.to.localeCompare(a.to))[0];if(p!==latest)return alert('Можна відкрити лише найпізніший закритий період.');const reason=prompt('Обов’язкова причина повторного відкриття:','');if(!reason)return;p.reopenedAt=new Date().toISOString();p.reopenedBy=currentUser.name;p.reopenReason=reason;p.snapshotStatus='скасовано';log('Повторно відкрито період',`${periodName(p)}; причина: ${reason}`);save();render()};

renderStatistics=()=>{const range=statisticRange(),list=rangeList(range.from,range.to).filter(t=>!isTransfer(t)),groups={};for(const t of list){const name=t.type==='opening_balance'?'Початковий залишок':t.cat||({contribution:'Внески партнерів',contribution_return:'Повернення внесків',payout:'Виплати прибутку'}[t.type]||'Без статті'),g=groups[name]??={name,count:0,income:0,expense:0,writeoff:0},signed=getSignedAmount(t);g.count++;if(['income','refund_out','contribution','opening_balance'].includes(t.type))g.income+=signed;else if(['expense','refund_in'].includes(t.type))g.expense-=signed;else g.writeoff-=signed}const rows=Object.values(groups),totals=rows.reduce((s,r)=>({count:s.count+r.count,income:s.income+r.income,expense:s.expense+r.expense,writeoff:s.writeoff+r.writeoff}),{count:0,income:0,expense:0,writeoff:0}),net=roundMoney(list.reduce((s,t)=>s+getSignedAmount(t),0));$('statisticsRows').innerHTML=rows.map(r=>`<tr><td>${r.name}</td><td>${r.count}</td><td class="amount income">${money(r.income)}</td><td class="amount expense">${money(r.expense)}</td><td class="amount">${money(r.writeoff)}</td><td class="amount">${money(r.income-r.expense-r.writeoff)}</td></tr>`).join('')||'<tr><td colspan="6">Даних немає</td></tr>';$('statisticsCount').textContent=totals.count;$('statisticsIncome').textContent=money(totals.income);$('statisticsExpense').textContent=money(totals.expense);$('statisticsWriteoff').textContent=money(totals.writeoff);$('statisticsNet').textContent=money(net);$('statisticsSummary').innerHTML=`<article><span>Надходження коштів</span><b>₴ ${money(totals.income)}</b></article><article><span>Операційні витрати</span><b>₴ ${money(totals.expense)}</b></article>`;$('statisticsPeriodLabel').textContent=range.from||range.to?`${range.from||'…'} — ${range.to||'…'}`:'Увесь час'};
