function buildSnapshot(start,end,reconciliation){const tools=periodTools(),report=computePeriodReport(start,end),balances=Object.fromEntries(Object.keys(accounts).map(account=>[account,getBalanceAt(account,end)])),rows=getActiveTransactions().filter(t=>t.isoDate>=start&&t.isoDate<=end),partners=computePartnerPositions(end),plannedAtClose=plannedPayments.filter(item=>!item.isDeleted&&item.status!=='cancelled'&&(!item.createdAt||item.createdAt.slice(0,10)<=end)).map(item=>{const paidAmount=roundMoney(getActiveTransactions().filter(tx=>tx.type==='expense'&&String(tx.plannedPaymentId)===String(item.id)&&tx.isoDate<=end).reduce((sum,tx)=>sum+valueOf(tx),0)),remaining=Math.max(0,roundMoney(item.amount-paidAmount));return{id:item.id,name:item.name,dueDate:item.dueDate,account:item.account,amount:item.amount,paidAmount,remaining,status:remaining>0?'planned':'paid'}}).filter(item=>item.remaining>0),snapshotPayments=plannedAtClose.map(item=>({...item,paidAmount:item.paidAmount,status:'planned'})),frozenByAccount=Object.fromEntries(Object.keys(accounts).map(account=>[account,accountFrozen(account,snapshotPayments,plannedSettings,end)])),plannedDeficit=roundMoney(Object.keys(accounts).reduce((sum,account)=>sum+Math.max(0,frozenByAccount[account]-balances[account]),0));return{balances,totalBalance:roundMoney(Object.values(balances).reduce((s,v)=>s+v,0)),reserveBalance:roundMoney(Object.entries(balances).filter(([account])=>accountSettings[account]?.isReserve).reduce((s,[,v])=>s+v,0)),loanDebts:Object.fromEntries(Object.entries(partners).map(([owner,value])=>[owner,value.loanDebt])),frozenByAccount,plannedPayments:plannedAtClose,plannedDeficit,reconciliation, ...report,cumulativeUndistributed:computeCumulativeUndistributed(end),partners,transactionCount:rows.length,checksum:tools.checksum(start,end)}}
function openPeriodWizard(){if(currentUser.role!=='Власник')return alert('Закривати періоди може лише користувач із роллю «Власник».');const start=expectedPeriodStart();if(!start)return alert('Немає операцій для закриття');const end=monthEnd(start),yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);periodWizard={step:1,start,end:end<=isoLocal(yesterday)?end:'',checks:[],reconciliation:{},comment:''};$('periodModal').classList.add('open');document.body.classList.add('modal-open');renderPeriodStep()}
