function renderPeriodStep(){const state=periodWizard,body=$('periodWizardBody');$('periodStepLabel').textContent=`Крок ${state.step} із 4`;$('periodBack').hidden=state.step===1;$('periodNext').textContent=state.step===4?'Закрити період':'Далі';
 if(state.step===1)body.innerHTML=`<div class="period-grid"><label class="field"><span>Початок</span><input value="${state.start}" readonly></label><label class="field"><span>Кінець <b>*</b></span><input id="periodEnd" type="date" value="${state.end}" max="${addDays(isoLocal(new Date()),-1)}"></label></div><div class="period-actions"><button class="btn secondary" data-period-quick="month">До кінця місяця</button><button class="btn secondary" data-period-quick="previous">Весь попередній місяць</button></div><p id="periodDateError" class="form-error" hidden></p>`;
 if(state.step===2){state.checks=periodChecks(state.start,state.end);const count=getActiveTransactions().filter(t=>t.isoDate>=state.start&&t.isoDate<=state.end).length;body.innerHTML=state.checks.map(c=>`<div class="period-check ${c.ok?'':c.blocking?'fail':'warn'}"><b>${c.ok?'✔':'✖'} ${c.name}</b>${c.details?`<p>${c.details}</p>`:''}</div>`).join('')+(count?'':`<div class="period-check warn">У періоді немає операцій</div>`)+`<button class="btn secondary" id="recheckPeriod">Перерахувати</button>`;$('periodNext').disabled=state.checks.some(c=>c.blocking&&!c.ok)}
 if(state.step===3){body.innerHTML=`<div class="table-wrap"><table class="reconcile-table"><thead><tr><th>Рахунок</th><th>У системі</th><th>Фактично</th><th>Різниця</th><th>Пояснення</th></tr></thead><tbody>${Object.keys(accounts).map(account=>{const r=state.reconciliation[account]||{},expected=getBalanceAt(account,state.end);return`<tr data-account="${account}"><td>${account}</td><td>${money(expected)}</td><td><input class="reconcile-actual" type="number" step="0.01" min="0" value="${r.actual??''}" required></td><td class="diff ${r.diff?'bad':''}">${money(r.diff||0)}</td><td><input class="reconcile-note" value="${r.note||''}" placeholder="Для розбіжності"></td></tr>`}).join('')}</tbody></table></div><label><input id="reconcileConfirm" type="checkbox" ${state.reconcileConfirmed?'checked':''}> Підтверджую, що розбіжність відома</label>`;validateReconciliation()}
 if(state.step===4){const snap=buildSnapshot(state.start,state.end,state.reconciliation);state.preview=snap;body.innerHTML=`<div class="period-summary">${[['Дохід',snap.income],['Витрати',snap.expenses],['Операційний прибуток',snap.operatingProfit],['Виплати',snap.payouts],['Нерозподілений результат',snap.cumulativeUndistributed],['Операцій',snap.transactionCount]].map(([k,v])=>`<div><small>${k}</small><br><b>${typeof v==='number'?money(v):v}</b></div>`).join('')}</div><h3>Залишки</h3><p>${Object.entries(snap.balances).map(([k,v])=>`${k}: ₴ ${money(v)}`).join('<br>')}</p><h3>Партнери</h3><p>${Object.entries(snap.partners).map(([k,v])=>`${k}: капітал ₴ ${money(v.capital)}, позика ₴ ${money(v.loanDebt)}`).join('<br>')}</p><label class="field"><span>Коментар</span><textarea id="periodComment">${state.comment}</textarea></label>`;$('periodNext').disabled=false}
}
function validateReconciliation(){if(periodWizard.step!==3)return;let complete=true,hasDiff=false,notesOk=true;document.querySelectorAll('#periodWizardBody tr[data-account]').forEach(row=>{const account=row.dataset.account,actualInput=row.querySelector('.reconcile-actual'),note=row.querySelector('.reconcile-note'),expected=getBalanceAt(account,periodWizard.end),valid=actualInput.value!==''&&Number(actualInput.value)>=0,actual=roundMoney(actualInput.value),diff=roundMoney(actual-expected);complete&&=valid;hasDiff||=diff!==0;notesOk&&=diff===0||note.value.trim().length>0;row.querySelector('.diff').textContent=money(diff);row.querySelector('.diff').classList.toggle('bad',diff!==0);periodWizard.reconciliation[account]={expected,actual,diff,note:note.value.trim()}});periodWizard.reconcileConfirmed=$('reconcileConfirm').checked;$('periodNext').disabled=!(complete&&notesOk&&(!hasDiff||periodWizard.reconcileConfirmed))}
