function renderClosedPeriods(){const latest=closedPeriods.filter(p=>p.status==='closed').sort((a,b)=>b.end.localeCompare(a.end))[0];$('closedPeriodRows').innerHTML=`<div class="period-actions" style="padding:12px 18px"><button class="btn secondary" id="checkAllPeriods">Перевірити цілісність усіх періодів</button></div><div class="table-wrap"><table><thead><tr><th>Період</th><th>Дата закриття</th><th>Хто</th><th>Прибуток</th><th>Розбіжності</th><th>Статус</th><th>Дії</th></tr></thead><tbody>${closedPeriods.map(p=>{const diffs=p.snapshot?Object.values(p.snapshot.reconciliation||{}).filter(x=>x.diff).length:'—',canReopen=p===latest&&p.status==='closed';return`<tr><td>${periodName(p)}${p.legacy?'<br><small>Старий формат, без знімка</small>':''}</td><td>${p.closedAt?new Date(p.closedAt).toLocaleString('uk-UA'):'—'}</td><td>${p.closedBy||'—'}</td><td>${p.snapshot?money(p.snapshot.operatingProfit):'—'}</td><td>${diffs}</td><td><span class="period-status ${p.status}">${p.status==='closed'?'Закрито':'Відкрито знову'}</span></td><td>${p.snapshot?`<button class="btn secondary" data-view-period="${p.id}">Переглянути знімок</button>`:`<button class="btn secondary" data-create-snapshot="${p.id}">Створити знімок</button>`}${canReopen?` <button class="btn secondary" data-reopen-period="${p.id}">Відкрити знову</button>`:p.status==='closed'?'<small> Спочатку відкрийте пізніші періоди</small>':''}</td></tr>`}).join('')||'<tr><td colspan="7">Закритих періодів немає</td></tr>'}</tbody></table></div>`;$('checkAllPeriods').onclick=()=>{const bad=closedPeriods.filter(p=>p.snapshot&&!snapshotIntegrity(p).ok);alert(bad.length?`Порушено цілісність: ${bad.map(periodName).join(', ')}`:'Цілісність усіх знімків підтверджено')}}
