const helpTip=key=>{const text=PERIOD_HELP[key]||'';return`<span class="help-tip" role="button" tabindex="0" aria-label="${text.replaceAll('"','&quot;')}" data-help="${text.replaceAll('"','&quot;')}">?</span>`};
const tooltipPortal=(()=>{const node=document.createElement('div');node.id='tooltipPortal';node.className='tooltip-portal';node.setAttribute('role','tooltip');document.body.append(node);return node})();
let activeHelpTip=null;
function positionTooltip(){if(!activeHelpTip)return;const gap=8,pad=12,rect=activeHelpTip.getBoundingClientRect(),box=tooltipPortal.getBoundingClientRect();let left=rect.left+rect.width/2-box.width/2,top=rect.top-box.height-gap;if(top<pad)top=rect.bottom+gap;left=Math.max(pad,Math.min(left,window.innerWidth-box.width-pad));top=Math.max(pad,Math.min(top,window.innerHeight-box.height-pad));tooltipPortal.style.left=`${Math.round(left)}px`;tooltipPortal.style.top=`${Math.round(top)}px`}
function showHelpTip(trigger){activeHelpTip=trigger;tooltipPortal.textContent=trigger.dataset.help||trigger.getAttribute('aria-label')||'';tooltipPortal.classList.add('visible');trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-describedby','tooltipPortal');requestAnimationFrame(positionTooltip)}
function hideHelpTip(trigger=activeHelpTip){if(trigger)trigger.setAttribute('aria-expanded','false');tooltipPortal.classList.remove('visible');activeHelpTip=null}
document.addEventListener('pointerover',e=>{const tip=e.target.closest('.help-tip');if(tip)showHelpTip(tip)});document.addEventListener('pointerout',e=>{const tip=e.target.closest('.help-tip');if(tip&&!tip.contains(e.relatedTarget))hideHelpTip(tip)});document.addEventListener('focusin',e=>{if(e.target.matches('.help-tip'))showHelpTip(e.target)});document.addEventListener('focusout',e=>{if(e.target.matches('.help-tip'))hideHelpTip(e.target)});document.addEventListener('click',e=>{const tip=e.target.closest('.help-tip');if(tip){e.preventDefault();activeHelpTip===tip?hideHelpTip(tip):showHelpTip(tip)}else hideHelpTip()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hideHelpTip();if((e.key==='Enter'||e.key===' ')&&e.target.matches('.help-tip')){e.preventDefault();activeHelpTip===e.target?hideHelpTip(e.target):showHelpTip(e.target)}});window.addEventListener('resize',positionTooltip);document.addEventListener('scroll',positionTooltip,true);

function renderPeriodCurrentState(){const yesterday=addDays(isoLocal(new Date()),-1),latest=closedPeriods.filter(p=>p.status==='closed').sort((a,b)=>b.end.localeCompare(a.end))[0],start=expectedPeriodStart(),count=start?getActiveTransactions().filter(t=>t.isoDate>=start&&t.isoDate<=yesterday).length:0,canClose=Boolean(start&&start<=yesterday&&count),previousEnd=(()=>{const d=new Date();d.setDate(0);return isoLocal(d)})(),recommended=start&&start<=previousEnd?previousEnd:'';$('periodCurrentState').innerHTML=`<article><small>Останній закритий період</small><b>${latest?periodName(latest):'Ще не закривався'}</b></article><article><small>Наступний період почнеться</small><b>${start||'Немає операцій'}</b></article><article><small>Можна закрити до</small><b>${yesterday}</b></article><article><small>Операцій у відкритому періоді</small><b>${count}</b></article>`;$('periodRecommendation').textContent=recommended?`Рекомендуємо закрити період до ${recommended}`:'Наразі немає повного періоду для рекомендації';const button=$('startPeriodClose');button.disabled=!canClose;button.title=canClose?'Відкрити майстер закриття':!start?'Немає операцій для закриття':!count?'У відкритому періоді немає операцій':'Усі завершені дні вже закриті'}

renderClosedPeriods=function(){const latest=closedPeriods.filter(p=>p.status==='closed').sort((a,b)=>b.end.localeCompare(a.end))[0],head=(label,key)=>`${label} ${helpTip(key)}`;$('closedPeriodRows').innerHTML=`<div class="period-actions" style="padding:12px 18px"><button class="btn secondary" id="checkAllPeriods">Перевірити цілісність усіх періодів</button></div><div class="table-wrap"><table><thead><tr><th>${head('Період','period')}</th><th>${head('Дата закриття','closedAt')}</th><th>${head('Хто закрив','closedBy')}</th><th>${head('Прибуток','profit')}</th><th>${head('Розбіжності','differences')}</th><th>${head('Статус','status')}</th><th>${head('Дії','actions')}</th></tr></thead><tbody>${closedPeriods.map(p=>{const difference=p.snapshot?roundMoney(Object.values(p.snapshot.reconciliation||{}).reduce((s,x)=>s+Math.abs(x.diff||0),0)):null,canReopen=p===latest&&p.status==='closed';return`<tr><td>${periodName(p)}${p.legacy?'<br><span class="status pending">Старий формат</span>':''}</td><td>${p.closedAt?new Date(p.closedAt).toLocaleString('uk-UA'):'—'}</td><td>${p.closedBy||'—'}</td><td>${p.snapshot?`₴ ${money(p.snapshot.operatingProfit)}`:'—'}</td><td>${difference===null?'—':`₴ ${money(difference)}`}</td><td><span class="period-status ${p.status}">${p.status==='closed'?'Закрито':'Відкрито знову'}</span></td><td><div class="period-row-actions">${p.snapshot?`<button class="btn secondary" data-view-period="${p.id}">Переглянути знімок</button><button class="btn secondary" data-check-period="${p.id}">Перевірити цілісність</button>`:`<button class="btn secondary" data-create-snapshot="${p.id}">Створити знімок</button>`}<button class="btn secondary" data-reopen-period="${canReopen?p.id:''}" ${canReopen?'':`disabled title="Спочатку відкрийте пізніші періоди"`}>Відкрити знову</button></div></td></tr>`}).join('')||'<tr><td colspan="7">Закритих періодів ще немає</td></tr>'}</tbody></table></div>`;$('checkAllPeriods').onclick=()=>{const bad=closedPeriods.filter(p=>p.snapshot&&!snapshotIntegrity(p).ok);alert(bad.length?`Порушено цілісність: ${bad.map(periodName).join(', ')}`:'Цілісність усіх знімків підтверджено')}};
$('closedPeriodRows').addEventListener('click',e=>{const id=e.target.dataset.checkPeriod;if(!id)return;e.preventDefault();e.stopImmediatePropagation();const p=closedPeriods.find(x=>String(x.id)===String(id)),result=snapshotIntegrity(p);alert(result.ok?'Цілісність знімка підтверджено':`Дані періоду змінилися: ${result.mismatches.join(', ')}`)},true);

const basePeriodStepRenderer=renderPeriodStep;renderPeriodStep=function(){basePeriodStepRenderer();const texts={1:['Вибір періоду','Оберіть, до якої дати закрити облік. Початок підставляється автоматично, щоб між періодами не було пропусків'],2:['Перевірки','Система шукає помилки в даних. Поки є червоні пункти, продовжити не можна'],3:['Звірка залишків','Порівняйте залишки в системі з реальними залишками з банківського застосунку або виписки станом на кінець останнього дня періоду'],4:['Підсумок','Ось що буде збережено у знімку періоду. Після підтвердження ці цифри більше не зміняться']},[title,description]=texts[periodWizard.step];$('periodModalTitle').textContent=title;$('periodWizardBody').insertAdjacentHTML('afterbegin',`<p class="wizard-explanation">${description}</p>`);const body=$('periodWizardBody');if(periodWizard.step===1){const labels=body.querySelectorAll('.field>span');labels[0].insertAdjacentHTML('beforeend',helpTip('start'));labels[1].insertAdjacentHTML('beforeend',helpTip('end'));body.querySelector('[data-period-quick="month"]').insertAdjacentHTML('beforeend',helpTip('monthEnd'));body.querySelector('[data-period-quick="previous"]').insertAdjacentHTML('beforeend',helpTip('previousMonth'))}if(periodWizard.step===2){body.querySelectorAll('.period-check b').forEach(el=>{const key=el.textContent.includes('від’ємних')?'negative':el.textContent.includes('переказ')?'transfers':el.textContent.includes('проведені')?'posted':'';if(key)el.insertAdjacentHTML('beforeend',helpTip(key));if(el.closest('.period-check').classList.contains('fail'))el.closest('.period-check').insertAdjacentHTML('beforeend','<button class="btn secondary" data-go-operations>Перейти до операцій</button>')})}if(periodWizard.step===3){const keys=['','system','actual','diff','note'];body.querySelectorAll('th').forEach((th,i)=>{if(keys[i])th.insertAdjacentHTML('beforeend',helpTip(keys[i]))});body.querySelector('label:last-child').insertAdjacentHTML('beforeend',helpTip('confirmDiff'));body.insertAdjacentHTML('beforeend','<p class="wizard-explanation">Порада: краще виправити розбіжність операцією до закриття.</p>')}if(periodWizard.step===4){const map={'Дохід':'income','Витрати':'expenses','Операційний прибуток':'operatingProfit','Виплати':'payouts','Нерозподілений результат':'undistributed','Операцій':'count'};body.querySelectorAll('.period-summary small').forEach(el=>el.insertAdjacentHTML('beforeend',helpTip(map[el.textContent])));body.querySelectorAll('h3')[0]?.insertAdjacentHTML('beforeend',helpTip('balances'));body.querySelectorAll('h3')[1]?.insertAdjacentHTML('beforeend',`${helpTip('capital')}${helpTip('loans')}`);body.querySelector('.field>span')?.insertAdjacentHTML('beforeend',helpTip('comment'))}};
