// Розподіл прибутку: нарахування зберігаються окремо від руху грошей.
const distributionApi=window.FinbaseDistribution;
let distributionWizard={step:1,start:'',end:'',comment:'',draftId:'',preview:null};
const reserveAccounts=()=>Object.keys(accounts).filter(account=>accountSettings[account]?.isReserve);
const operatingAccounts=()=>Object.keys(accounts).filter(account=>!accountSettings[account]?.isReserve);
const reserveBalance=(to='')=>roundMoney(reserveAccounts().reduce((sum,account)=>sum+balanceFor(account,transactions,to),0));
const totalBalance=(to='')=>roundMoney(Object.keys(accounts).reduce((sum,account)=>sum+balanceFor(account,transactions,to),0));
const freeCash=(to='')=>roundMoney(totalBalance(to)-reserveBalance(to));
function plannedFinancials(today=isoLocal(new Date())){const balances=Object.fromEntries(Object.keys(accounts).map(account=>[account,balanceFor(account)])),frozenByAccount=Object.fromEntries(Object.keys(accounts).map(account=>[account,accountFrozen(account,plannedPayments,plannedSettings,today)])),availableByAccount=Object.fromEntries(Object.keys(accounts).map(account=>[account,accountAvailable(account,balances[account],plannedPayments,plannedSettings,today)])),deficitByAccount=Object.fromEntries(Object.keys(accounts).map(account=>[account,Math.max(0,roundMoney(frozenByAccount[account]-balances[account]))])),frozenTotal=roundMoney(Object.values(frozenByAccount).reduce((sum,value)=>sum+value,0)),deficit=roundMoney(Object.values(deficitByAccount).reduce((sum,value)=>sum+value,0)),freeMoney=window.FinbaseAccounting.freeMoney(balances,plannedPayments,plannedSettings,{reserveAccount:reserveAccounts()[0]||''},today);return{balances,frozenByAccount,availableByAccount,deficitByAccount,frozenTotal,deficit,freeMoney}}
const largestOperatingAccount=(to='')=>operatingAccounts().sort((a,b)=>balanceFor(b,transactions,to)-balanceFor(a,transactions,to))[0]||'';
const loanDebts=(to='')=>Object.fromEntries(owners.map(owner=>[owner,roundMoney(computePartnerPositions(to)[owner]?.loanDebt||0)]));
function internalTransfer(from,to,value,date,description,extra={}){assertAccountAvailable(from,value,'transfer');const transferId=newId(),base={isoDate:date,time:'23:55',date:new Date(`${date}T12:00:00`).toLocaleDateString('uk-UA'),value:roundMoney(value),status:'Проведено',party:'—',cat:'',color:'#b87816',transferId,isTransfer:true,desc:description,...extra};return[{...base,id:newId(),transferOrder:1,type:'expense',account:from},{...base,id:newId(),transferOrder:2,type:'income',account:to}]}
const distributionShares=()=>Object.fromEntries(owners.map(owner=>[owner,roundMoney(manualShares[owner]||0)]));
const distributionShareSum=()=>roundMoney(Object.values(distributionShares()).reduce((sum,value)=>sum+value,0));
const approvedDistributions=()=>distributions.filter(item=>item.status==='approved');
