async function createProportionalPayouts(){const availability=distributionAvailability(),allocations=distributionApi.proportionalPayments(availability.unpaid,availability.available,distributionShares());if(!Object.values(allocations).some(value=>value>=.01))return alert('Немає доступної суми для виплати.');if(!confirm(`Створити виплати на ₴ ${money(Object.values(allocations).reduce((s,v)=>s+v,0))} пропорційно часткам?`))return;const day=isoLocal(new Date());try{assertDateOpen(day,'Виплата')}catch(error){return alert(error.message)}const balances=Object.fromEntries(Object.keys(accounts).map(account=>[account,Math.max(0,balanceFor(account))]));for(const owner of owners){let due=allocations[owner]||0;for(const account of Object.keys(accounts)){if(due<.01)break;const value=roundMoney(Math.min(due,Math.max(0,accountAvailable(account,balances[account],plannedPayments,plannedSettings,day))));if(value<.01)continue;try{availabilityCheckContext={balance:balances[account],plannedPayments};assertAccountAvailable(account,value,'payout')}catch(error){availabilityCheckContext=null;alert(error.message);return}availabilityCheckContext=null;transactions.unshift({id:newId(),isoDate:day,time:new Date().toTimeString().slice(0,5),date:new Date().toLocaleDateString('uk-UA'),value,status:'Проведено',party:owner,type:'payout',cat:'',color:'#7a8492',desc:'Пропорційна виплата нарахованого прибутку',account});balances[account]=roundMoney(balances[account]-value);due=roundMoney(due-value)}}log('Створено пропорційні виплати',owners.map(owner=>`${owner}: ₴ ${money(allocations[owner]||0)}`).join('; '));await save();render()}
