function aiTime(){return new Intl.DateTimeFormat('uk-UA',{hour:'2-digit',minute:'2-digit'}).format(new Date())}
function renderAiText(text){const escape=value=>String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'),inline=value=>escape(value).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');const lines=String(text||'').split(/\r?\n/),parts=[];let list=[];const flush=()=>{if(list.length){parts.push(`<ul>${list.map(row=>`<li>${inline(row)}</li>`).join('')}</ul>`);list=[]}};for(const line of lines){const item=line.match(/^\s*[-•]\s+(.+)/);if(item){list.push(item[1]);continue}flush();const heading=line.match(/^\s*#{1,4}\s+(.+)/);if(heading)parts.push(`<h3>${inline(heading[1])}</h3>`);else if(line.trim())parts.push(`<p>${inline(line.trim())}</p>`);else parts.push('<span class="ai-spacer"></span>')}flush();return parts.join('')}
function addAiMessage(text,role='assistant'){const item=document.createElement('div');item.className=`ai-message ${role}`;item.innerHTML=`${role!=='user'?'<span class="ai-message-avatar" aria-hidden="true">AI</span>':''}<div><div class="ai-message-content"></div><time>${aiTime()}</time></div>`;const content=item.querySelector('.ai-message-content');if(role==='user')content.textContent=text;else content.innerHTML=renderAiText(text);aiMessages.append(item);aiMessages.scrollTop=aiMessages.scrollHeight;return item}
function getAiAnswer(question){const q=question.toLocaleLowerCase('uk-UA'),active=getActiveTransactions(),income=roundMoney(active.filter(t=>t.type==='income').reduce((s,t)=>s+valueOf(t),0)),expense=roundMoney(active.filter(t=>t.type==='expense').reduce((s,t)=>s+valueOf(t),0)),balance=roundMoney(totalBalance()),profit=roundMoney(income-expense);if(/привіт|вітаю|добр(ий|ого)/.test(q))return 'Вітаю! Запитайте мене про баланс, доходи, витрати, прибуток або рахунки — я використаю актуальні дані обліку.';if(/баланс|залишок|скільки.*(гро|кошт)/.test(q))return `Поточний загальний баланс: ₴ ${money(balance)}. Дані розраховано за ${active.length} активними операціями.`;if(/дохід|доход|надходжен/.test(q)&&/витрат/.test(q))return `За весь період:\n• доходи — ₴ ${money(income)};\n• витрати — ₴ ${money(expense)};\n• різниця — ₴ ${money(profit)}.`;if(/дохід|доход|надходжен/.test(q))return `Загальна сума доходів за весь період: ₴ ${money(income)}.`;if(/витрат/.test(q))return `Загальна сума витрат за весь період: ₴ ${money(expense)}.`;if(/прибут|результат/.test(q))return `${profit>=0?'Чистий фінансовий результат':'Збиток'} за весь період: ₴ ${money(Math.abs(profit))}. Це доходи мінус операційні витрати.`;if(/рахунк|каса|mono|нова.?pay|novapay/.test(q)){const rows=Object.keys(accounts).map(name=>`• ${name}: ₴ ${money(balanceFor(name))}`);return `Залишки за рахунками:\n${rows.join('\n')}`;}if(/транзакц|операці/.test(q))return `У системі ${active.length} активних операцій: ${active.filter(t=>t.type==='income').length} доходів і ${active.filter(t=>t.type==='expense').length} витрат.`;return 'Я поки що найкраще відповідаю на запитання про баланс, доходи, витрати, прибуток, транзакції та залишки на рахунках. Спробуйте сформулювати запит із одним із цих показників.'}
function getAssistantContext(){const today=isoLocal(new Date()),through=addDays(today,45),planned=plannedFinancials(today),coverageByMonth=window.FinbaseAccounting.coverageByMonth(planned.balances,plannedPayments,plannedSettings,today),upcoming=plannedPayments.filter(item=>item.status==='planned'&&!item.isDeleted&&item.dueDate>=today&&item.dueDate<=through).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).map(item=>({name:item.name,date:item.dueDate,remaining:window.FinbasePlannedPayments.remainingAmount(item),account:item.account})),warnings=Object.entries(planned.deficitByAccount).filter(([,value])=>value>0).map(([account,value])=>`Дефіцит планових платежів на рахунку «${account}»: ${money(value)} грн`);return{today,currentSection:[...document.querySelectorAll('.main-nav a')].find(x=>x.classList.contains('active'))?.textContent?.trim()||'Операції',user:{name:currentUser.name,role:currentUser.role},features:{plannedPayments:true},accounts:Object.fromEntries(Object.keys(accounts).map(name=>[name,{balance:planned.balances[name],frozen:planned.frozenByAccount[name],available:planned.availableByAccount[name],isReserve:accountSettings[name].isReserve}])),totals:{frozenTotal:planned.frozenTotal,freeMoney:planned.freeMoney},upcomingPlannedPayments:upcoming,coverageByMonth,warnings,transactions:getActiveTransactions(),closedPeriods,manualShares,distributionSettings,distributions}}
