async function loadAiSourceContext(){if(aiSourceContext)return aiSourceContext;const files=['index.html','app.js','accounting-core.js','period-core.js','distribution-core.js','docs/assistant-knowledge.md'];const sources=await Promise.all(files.map(async file=>{try{return`\n===== ${file} =====\n${await(await fetch(file,{cache:'no-store'})).text()}`}catch{return`\n===== ${file}: недоступний =====`}}));aiSourceContext=sources.join('').replace(/password\s*:\s*['"][^'"]*['"]/gi,"password:'[REDACTED]'").replace(/apiKey\s*:\s*['"][^'"]*['"]/gi,"apiKey:'[REDACTED]'").slice(0,120000);return aiSourceContext}
function aiInstructions(){return`Ти — вбудований україномовний професійний помічник з управлінського обліку у Finbase. Для питань з методології насамперед використовуй підключений посібник через file_search, а для даних компанії — переданий актуальний стан і код системи. Чітко відрізняй фактичні дані системи, положення посібника та власні рекомендації. Аналізуй фінанси точно, не вигадуй значень, цитат або номерів сторінок. Якщо користувач хоче виконати дію, дай коротку покрокову інструкцію з точними українськими назвами розділів і кнопок. Ти лише консультуєш і не стверджуй, що вже натиснув кнопку чи змінив дані. Попереджай перед незворотними або фінансовими діями. Посібник видано 2017 року: для податкових, правових і нормативних тверджень попереджай, що вони могли застаріти. Не показуй API-ключ і не проси його в чаті. Якщо даних недостатньо, скажи це прямо.`}
function responseText(data){if(typeof data.output_text==='string')return data.output_text;return(data.output||[]).flatMap(item=>item.content||[]).filter(item=>item.type==='output_text').map(item=>item.text).join('\n').trim()}
async function openAiRequest(path,key,options={}){const url=path==='/responses'?'https://api.openai.com/v1/responses':`https://api.openai.com/v1${path}`;const response=await fetch(url,{...options,headers:{Authorization:`Bearer ${key}`,...options.headers}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error?.message||`OpenAI API повернув помилку ${response.status}.`);return data}
async function connectManagementAccountingGuide(file){const key=localStorage.getItem(AI_KEY);if(!key)throw new Error('Спочатку збережіть OpenAI API-ключ.');if(!file||(!file.name.toLowerCase().endsWith('.pdf')&&file.type!=='application/pdf'))throw new Error('Оберіть PDF-файл посібника.');const button=$('aiKnowledgeConnect'),status=$('aiKnowledgeStatus');button.disabled=true;status.textContent='Завантаження…';try{const form=new FormData();form.append('purpose','assistants');form.append('file',file);const uploaded=await openAiRequest('/files',key,{method:'POST',body:form});status.textContent='Створення бази знань…';const store=await openAiRequest('/vector_stores',key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'Finbase — Управлінський облік (2017)'})});const attached=await openAiRequest(`/vector_stores/${store.id}/files`,key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file_id:uploaded.id,attributes:{source:'management-accounting-2017',language:'uk'}})});status.textContent='Індексація…';for(let attempt=0;attempt<60;attempt++){const current=await openAiRequest(`/vector_stores/${store.id}/files/${attached.id}`,key);if(current.status==='completed'){localStorage.setItem(AI_VECTOR_STORE_KEY,store.id);syncAiSettings();addAiMessage('Посібник з управлінського обліку підключено. Тепер я використовую його для професійних пояснень і рекомендацій.');return}if(current.status==='failed'||current.last_error)throw new Error(current.last_error?.message||'OpenAI не зміг проіндексувати PDF.');await new Promise(resolve=>setTimeout(resolve,1500))}throw new Error('Індексація триває довше очікуваного. Спробуйте підключити PDF ще раз за кілька хвилин.')}finally{button.disabled=false}}
async function askOpenAi(question){const key=localStorage.getItem(AI_KEY);if(!key)throw new Error('Спочатку додайте OpenAI API-ключ у налаштуваннях ⚙.');const source=await loadAiSourceContext(),state=aiStateContext(),conversation=aiHistory.slice(-8).map(x=>`${x.role==='user'?'Користувач':'Помічник'}: ${x.text}`).join('\n'),vectorStoreId=localStorage.getItem(AI_VECTOR_STORE_KEY);const payload={model:localStorage.getItem(AI_MODEL_KEY)||'gpt-5.4-mini',instructions:aiInstructions(),input:`ПОПЕРЕДНІЙ ДІАЛОГ:\n${conversation||'Немає'}\n\nАКТУАЛЬНИЙ СТАН СИСТЕМИ:\n${state}\n\nВИХІДНИЙ КОД СИСТЕМИ:\n${source}\n\nПИТАННЯ КОРИСТУВАЧА:\n${question}`,max_output_tokens:1800};if(vectorStoreId)payload.tools=[{type:'file_search',vector_store_ids:[vectorStoreId],max_num_results:5}];const data=await openAiRequest('/responses',key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const text=responseText(data);if(!text)throw new Error('OpenAI не повернув текстової відповіді.');return text}
async function submitAiMessage(text){const value=String(text||'').trim();if(!value)return;if(!localStorage.getItem(AI_KEY)){aiSettings.hidden=false;$('aiSettingsToggle').setAttribute('aria-expanded','true');addAiMessage('Спочатку вставте API-ключ у налаштуваннях ⚙.','error');aiApiKey.focus();return}addAiMessage(value,'user');aiHistory.push({role:'user',text:value});aiInput.value='';aiInput.style.height='auto';$('aiSuggestions').hidden=true;const submit=$('aiChatForm').querySelector('button[type="submit"]');submit.disabled=true;const typing=addAiMessage('','assistant');typing.classList.add('ai-typing');typing.querySelector('.ai-message-content').innerHTML='<i></i><i></i><i></i>';try{const answer=await askOpenAi(value);typing.remove();addAiMessage(answer);aiHistory.push({role:'assistant',text:answer})}catch(error){typing.remove();addAiMessage(error.message,'error')}finally{submit.disabled=false;aiInput.focus()}}
function syncAiSettings(){const connected=Boolean(localStorage.getItem(AI_KEY)),guideConnected=Boolean(localStorage.getItem(AI_VECTOR_STORE_KEY));aiStatus.textContent=connected?'OpenAI підключено · ключ збережено постійно':'Потрібен API-ключ';aiModel.value=localStorage.getItem(AI_MODEL_KEY)||'gpt-5.4-mini';aiApiKey.value='';aiApiKey.placeholder=connected?'Ключ збережено — введіть новий для заміни':'sk-…';$('aiKnowledgeStatus').textContent=guideConnected?'Підключено ✓':'Не підключено'}
$('aiKnowledgeConnect').onclick=()=>$('aiKnowledgeFile').click();$('aiKnowledgeFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{await connectManagementAccountingGuide(file)}catch(error){$('aiKnowledgeStatus').textContent='Помилка';addAiMessage(error.message,'error')}finally{e.target.value=''}};
aiLauncher.onclick=()=>toggleAiChat();$('aiChatClose').onclick=()=>toggleAiChat(false);$('aiSettingsToggle').onclick=()=>{aiSettings.hidden=!aiSettings.hidden;$('aiSettingsToggle').setAttribute('aria-expanded',String(!aiSettings.hidden));if(!aiSettings.hidden)aiApiKey.focus()};aiSettings.onsubmit=e=>{e.preventDefault();const key=aiApiKey.value.trim(),model=aiModel.value.trim()||'gpt-5.4-mini';if(key)localStorage.setItem(AI_KEY,key);localStorage.setItem(AI_MODEL_KEY,model);aiSettings.hidden=true;$('aiSettingsToggle').setAttribute('aria-expanded','false');syncAiSettings();addAiMessage(key?'OpenAI підключено. Ключ збережено постійно на цьому пристрої.':'Налаштування моделі оновлено; збережений ключ не змінено.')};$('aiKeyClear').onclick=()=>{localStorage.removeItem(AI_KEY);aiHistory=[];syncAiSettings();addAiMessage('API-ключ видалено з цього пристрою.')};$('aiChatForm').onsubmit=e=>{e.preventDefault();submitAiMessage(aiInput.value)};$('aiSuggestions').onclick=e=>{const button=e.target.closest('button');if(button)submitAiMessage(button.textContent)};aiInput.addEventListener('input',()=>{aiInput.style.height='auto';aiInput.style.height=`${Math.min(aiInput.scrollHeight,112)}px`});aiInput.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.currentTarget.form.requestSubmit()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&aiAssistant.classList.contains('open'))toggleAiChat(false)});syncAiSettings();

