const plannedView=document.createElement('section');plannedView.id='plannedView';plannedView.className='planned-view';plannedView.hidden=true;plannedView.innerHTML=`<div class="page-head"><div><div class="eyebrow"><span>Фінанси</span><b>/</b><strong>Планові платежі</strong></div><h1>Планові платежі</h1><p>Контроль майбутніх зобов’язань і доступних коштів</p></div><div class="head-actions"><button class="btn primary" id="newPlannedPayment">Новий платіж</button><button class="btn secondary" id="createFromTemplates">Створити платежі з шаблонів на місяць</button><button class="btn secondary" id="manageTemplates">Шаблони</button><button class="btn secondary" id="manageTaxRules">Правила податків</button></div></div><section class="sheet-card planned-controls"><div class="tabs"><button class="tab active" data-planned-mode="months">За місяцями</button><button class="tab" data-planned-mode="list">Список</button></div><div class="planned-filters"><select id="plannedAccountFilter"><option value="">Усі рахунки</option></select><select id="plannedKindFilter"><option value="">Усі види</option></select><select id="plannedStatusFilter"><option value="">Усі статуси</option><option value="planned">Заплановано</option><option value="paid">Сплачено</option><option value="cancelled">Скасовано</option></select><input id="plannedPeriodFilter" type="month" aria-label="Період"></div></section><section class="sheet-card coverage-card"><div class="accounts-table-head"><div><h2>Покриття на наступні місяці</h2><p>Потрібна сума, покриття та дефіцит</p></div></div><div id="plannedCoverage"></div></section><div id="plannedPaymentsContent"></div>`;document.querySelector('main').append(plannedView);
const dashboardPlanned=document.createElement('section');dashboardPlanned.className='summary-grid transaction-view planned-dashboard';dashboardPlanned.innerHTML='<article class="summary-card"><div class="card-label">Прострочені платежі</div><div class="metric" id="overduePlannedMetric">0</div></article><article class="summary-card"><div class="card-label">Платежі на 7 днів</div><div class="metric" id="weekPlannedMetric">₴ 0,00</div></article><article class="summary-card"><div class="card-label">Дефіцит покриття</div><div class="metric" id="plannedDeficitMetric">₴ 0,00</div></article>';document.querySelector('.migration-panel').before(dashboardPlanned);
const plannedPaymentModal=document.createElement('div');plannedPaymentModal.id='plannedPaymentModal';plannedPaymentModal.className='modal-backdrop planned-payment-modal';plannedPaymentModal.setAttribute('aria-hidden','true');plannedPaymentModal.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="plannedPaymentModalTitle"><div class="modal-head"><div class="modal-title-group"><span class="modal-title-icon"><svg><use href="#i-arrow-up"/></svg></span><div><h2 id="plannedPaymentModalTitle">Новий плановий платіж</h2><p id="plannedPaymentModalSubtitle">Заплануйте майбутню витрату</p></div></div><button class="modal-close" id="closePlannedPaymentModal" type="button" aria-label="Закрити"><svg><use href="#i-x"/></svg></button></div><form id="plannedPaymentForm"><div class="form-body"><label class="field amount-field planned-transaction-amount"><span>Сума <b>*</b></span><div class="money-input"><span class="currency-symbol">₴</span><input name="amount" type="number" min="0.01" step="0.01" placeholder="0,00" inputmode="decimal" required><strong>UAH</strong></div></label><label class="field planned-category-field"><span>Стаття витрат <b>*</b></span><select name="category" required></select></label><label class="field planned-custom-category" hidden><span>Власна стаття <b>*</b></span><input name="customCategory" maxlength="80" placeholder="Введіть назву статті"></label><div class="form-row planned-form-row"><label class="field"><span>Дата оплати <b>*</b></span><input name="dueDate" type="date" required></label><label class="field"><span>Рахунок <b>*</b></span><select name="account" required></select><span class="available-balance" id="plannedAccountBalance">Оберіть рахунок</span></label></div><label class="field planned-comment-field"><span>Коментар</span><textarea name="note" rows="3" maxlength="300" placeholder="Додайте деталі до планового платежу..."></textarea><small><span id="plannedCommentCount">0</span>/300</small></label><label class="field planned-change-comment" hidden><span>Причина зміни <b>*</b></span><input name="changeComment" minlength="5" placeholder="Щонайменше 5 символів"></label><div class="form-error" id="plannedPaymentError" role="alert" hidden></div></div><div class="modal-footer"><div class="operation-total"><span>Буде зарезервовано</span><b id="plannedModalTotal">− ₴ 0,00</b></div><div class="modal-footer-actions"><button class="btn secondary" id="cancelPlannedPayment" type="button">Скасувати</button><button class="btn primary" type="submit" id="savePlannedPayment"><svg><use href="#i-plus"/></svg>Створити платіж</button></div></div></form></section>`;document.body.append(plannedPaymentModal);
let plannedViewMode='months',taxWarnings=[],plannedFilterState={account:'',kind:'',status:'',month:''};
const escapeHtml=value=>String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
function assertPlannedOwner(){if(currentUser.role!=='Власник')throw new Error('Керувати правилами й шаблонами може лише Власник.')}
function recalculateTaxState(){const result=window.FinbasePlannedPayments.recalculateTaxPayments({rules:taxRules,payments:plannedPayments,transactions:getActiveTransactions(),closedPeriods});if(result.changes.length){result.changes.forEach(change=>log('Перераховано податковий платіж',`${JSON.stringify(change.old)} → ${JSON.stringify(change.new)}`));plannedPayments=result.payments;save()}taxWarnings=result.warnings}
function plannedFilters(){return plannedFilterState}
function filteredPlannedPayments(){const f=plannedFilters();return plannedPayments.filter(item=>(!f.account||item.account===f.account)&&(!f.kind||item.kind===f.kind)&&(!f.status||item.status===f.status)&&(!f.month||String(item.dueDate).startsWith(f.month)))}
function plannedRow(item){const remaining=window.FinbasePlannedPayments.remainingAmount(item),warning=item.amount<item.paidAmount?'<span class="status cancelled">Сума менша за сплачену</span>':'';return`<article class="planned-row"><div><b>${escapeHtml(item.name)}</b>${item.isEstimate?'<span class="status pending">Розрахункова сума</span>':''}${warning}<small>${item.dueDate} · ${escapeHtml(item.account)} · ${escapeHtml(item.category||item.name)}</small>${item.note?`<small>${escapeHtml(item.note)}</small>`:''}</div><div class="planned-amounts"><span>Сума <b>₴ ${money(item.amount)}</b></span><span>Сплачено <b>₴ ${money(item.paidAmount)}</b></span><span>Залишок <b>₴ ${money(remaining)}</b></span></div><span class="period-status ${item.status}">${item.status==='planned'?'Заплановано':item.status==='paid'?'Сплачено':'Скасовано'}</span><div class="period-row-actions">${item.status==='planned'&&!item.isDeleted?`<button class="btn primary compact" data-pay-planned="${item.id}">Сплатити</button><button class="btn secondary compact" data-edit-planned="${item.id}">Редагувати</button><button class="btn secondary compact" data-cancel-planned="${item.id}">Скасувати</button>`:''}</div></article>`}
function renderPlannedPayments(){recalculateTaxState();$('plannedAccountFilter').innerHTML='<option value="">Усі рахунки</option>'+Object.keys(accounts).map(value=>`<option>${escapeHtml(value)}</option>`).join('');$('plannedKindFilter').innerHTML='<option value="">Усі види</option>'+window.FinbasePlannedPayments.kinds.map(value=>`<option value="${value}">${value}</option>`).join('');const items=filteredPlannedPayments().sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate))),balances=Object.fromEntries(Object.keys(accounts).map(account=>[account,balanceFor(account)])),coverage=window.FinbaseAccounting.coverageByMonth(balances,plannedPayments,plannedSettings,isoLocal(new Date()));$('plannedCoverage').innerHTML=coverage.map(row=>`<div class="coverage-row"><div><b>${row.month}</b><span>Потрібно ₴ ${money(row.required)} · Покрито ₴ ${money(row.covered)} · Дефіцит ₴ ${money(row.deficit)}</span></div><progress max="100" value="${Math.min(100,row.percent)}"></progress><b>${money(row.percent)}%</b></div>`).join('')||'<p class="empty-state">У горизонті немає платежів.</p>';if(plannedViewMode==='list')$('plannedPaymentsContent').innerHTML=`<section class="sheet-card planned-list">${items.map(plannedRow).join('')||'<p class="empty-state">Платежів не знайдено.</p>'}</section>`;else{const groups={};items.forEach(item=>(groups[String(item.dueDate).slice(0,7)]??=[]).push(item));$('plannedPaymentsContent').innerHTML=Object.entries(groups).map(([month,rows])=>{const summary=coverage.find(item=>item.month===month)||{required:rows.reduce((sum,item)=>sum+window.FinbasePlannedPayments.remainingAmount(item),0),covered:0,deficit:0};return`<section class="sheet-card planned-month"><div class="accounts-table-head"><div><h2>${month}</h2><p>Потрібно ₴ ${money(summary.required)} / Покрито ₴ ${money(summary.covered)} / Дефіцит ₴ ${money(summary.deficit)}</p></div></div>${rows.map(plannedRow).join('')}</section>`}).join('')||'<section class="sheet-card"><p class="empty-state">Платежів не знайдено.</p></section>'}}
const plannedExpenseCategories=[...document.querySelectorAll('#transactionCategory option')].map(option=>option.value).filter(Boolean);
const plannedKindByCategory=category=>category==='Податки'?'tax':category==='Закупка'?'goods':category.startsWith('Доставка')?'delivery':'other';
let editedPlannedPayment=null,plannedModalReturnFocus=null;
function selectedPlannedCategory(form){return form.elements.category.value==='__custom__'?form.elements.customCategory.value.trim():form.elements.category.value}
function updatePlannedModalSummary(){const form=$('plannedPaymentForm'),amount=Number(form.elements.amount.value||0),account=form.elements.account.value,custom=form.elements.category.value==='__custom__';form.querySelector('.planned-custom-category').hidden=!custom;form.elements.customCategory.required=custom;$('plannedModalTotal').textContent=`− ₴ ${money(amount)}`;$('plannedCommentCount').textContent=form.elements.note.value.length;$('plannedAccountBalance').innerHTML=account?`Доступно зараз <strong>₴ ${money(balanceFor(account))}</strong>`:'Оберіть рахунок'}
function closePlannedPaymentModal(){plannedPaymentModal.classList.remove('open');plannedPaymentModal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');plannedModalReturnFocus?.focus();editedPlannedPayment=null}
function openPlannedPaymentModal(existing=null){editedPlannedPayment=existing;plannedModalReturnFocus=document.activeElement;const form=$('plannedPaymentForm'),isEdit=Boolean(existing),category=existing?.category||existing?.name||'';form.reset();$('plannedPaymentModalTitle').textContent=isEdit?'Редагувати плановий платіж':'Новий плановий платіж';$('plannedPaymentModalSubtitle').textContent=isEdit?'Оновіть дані майбутньої витрати':'Заплануйте майбутню витрату';$('savePlannedPayment').innerHTML=isEdit?'Зберегти зміни':'<svg><use href="#i-plus"/></svg>Створити платіж';const changeComment=form.querySelector('.planned-change-comment');changeComment.hidden=!isEdit;form.elements.changeComment.required=isEdit;form.elements.category.innerHTML='<option value="" disabled>Оберіть статтю витрат</option>'+plannedExpenseCategories.map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('')+'<option value="__custom__">＋ Власна стаття…</option>';form.elements.account.innerHTML=Object.keys(accounts).map(value=>`<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`).join('');if(category&&plannedExpenseCategories.includes(category))form.elements.category.value=category;else if(category){form.elements.category.value='__custom__';form.elements.customCategory.value=category}else form.elements.category.value='';form.elements.amount.value=existing?.amount||'';form.elements.account.value=existing?.account||Object.keys(accounts)[0]||'';form.elements.dueDate.value=existing?.dueDate||isoLocal(new Date());form.elements.note.value=existing?.note||'';$('plannedPaymentError').hidden=true;updatePlannedModalSummary();plannedPaymentModal.classList.add('open');plannedPaymentModal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');setTimeout(()=>form.elements.amount.focus(),0)}
$('closePlannedPaymentModal').onclick=closePlannedPaymentModal;$('cancelPlannedPayment').onclick=closePlannedPaymentModal;plannedPaymentModal.onclick=e=>{if(e.target===plannedPaymentModal)closePlannedPaymentModal()};$('plannedPaymentForm').oninput=updatePlannedModalSummary;$('plannedPaymentForm').onchange=updatePlannedModalSummary;$('plannedPaymentForm').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,error=$('plannedPaymentError'),existing=editedPlannedPayment,category=selectedPlannedCategory(form);if(!category){error.textContent='Оберіть або введіть статтю витрат.';error.hidden=false;return}const input={id:existing?.id||newId(),name:category,category,kind:plannedKindByCategory(category),account:form.elements.account.value,amount:Number(form.elements.amount.value),paidAmount:Number(existing?.paidAmount||0),dueDate:form.elements.dueDate.value,status:existing?.status||'planned',basisMonth:existing?.basisMonth,isEstimate:Boolean(existing?.isEstimate),note:form.elements.note.value.trim(),createdBy:existing?.createdBy||currentUser.name,createdAt:existing?.createdAt||new Date().toISOString(),isDeleted:Boolean(existing?.isDeleted)};try{if(existing)window.financePlannedPayments.update(existing.id,input,form.elements.changeComment.value);else window.financePlannedPayments.create(input);closePlannedPaymentModal();renderPlannedPayments();renderPlannedDashboard()}catch(err){error.textContent=err.message;error.hidden=false}};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&plannedPaymentModal.classList.contains('open'))closePlannedPaymentModal()});
function manageTemplates(){try{assertPlannedOwner()}catch(error){return alert(error.message)}const list=plannedTemplates.map((item,index)=>`${index+1}. ${item.name} · ₴ ${money(item.amount)} · день ${item.dayOfMonth} · ${item.active?'активний':'вимкнений'}`).join('\n'),choice=prompt(`${list||'Шаблонів немає.'}\n\nВведіть номер для редагування або 0 для нового:`,'0');if(choice===null)return;const previous=Number(choice)>0?plannedTemplates[Number(choice)-1]:null;if(Number(choice)>0&&!previous)return alert('Шаблон не знайдено.');const name=prompt('Назва шаблону:',previous?.name||'');if(!name)return;const kind=prompt(`Вид (${window.FinbasePlannedPayments.kinds.join(', ')}):`,previous?.kind||'other'),account=prompt('Рахунок:',previous?.account||Object.keys(accounts)[0]),amount=Number(prompt('Сума:',previous?.amount||'')),dayOfMonth=Math.max(1,Math.min(31,Number(prompt('День місяця:',previous?.dayOfMonth||'1'))||1)),next={id:previous?.id||newId(),name,kind,account,amount,dayOfMonth,active:confirm('Шаблон активний?')};if(!window.FinbasePlannedPayments.kinds.includes(kind)||!accounts[account]||!(amount>0))return alert('Перевірте вид, рахунок і суму.');if(previous)plannedTemplates[plannedTemplates.indexOf(previous)]=next;else plannedTemplates.push(next);log('Змінено шаблони планових платежів',`${JSON.stringify(previous)} → ${JSON.stringify(next)}`);save();renderPlannedPayments()}
function createFromTemplates(){try{assertPlannedOwner()}catch(error){return alert(error.message)}const month=prompt('Місяць платежів (РРРР-ММ):',isoLocal(new Date()).slice(0,7));if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month||''))return;const rows=plannedTemplates.filter(item=>item.active&&!plannedPayments.some(payment=>payment.templateId===item.id&&payment.basisMonth===month)).map(item=>({...item,id:newId(),paidAmount:0,dueDate:`${month}-${String(Math.min(item.dayOfMonth,new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate())).padStart(2,'0')}`,status:'planned',basisMonth:month,isEstimate:false,note:'Створено з шаблону',createdBy:currentUser.name,createdAt:new Date().toISOString(),isDeleted:false,templateId:item.id}));if(!rows.length)return alert('Немає активних шаблонів для створення.');if(!confirm(rows.map(item=>`${item.name}: ₴ ${money(item.amount)}, ${item.dueDate}`).join('\n')))return;plannedPayments.push(...rows);log('Створено платежі з шаблонів',JSON.stringify(rows));save();renderPlannedPayments()}
function manageTaxRules(){try{assertPlannedOwner()}catch(error){return alert(error.message)}const list=taxRules.map((item,index)=>`${index+1}. ${item.name}: ${item.basis==='fixed'?'₴':'%'} ${item.value}, день ${item.payDay}, ${item.active?'активне':'вимкнене'}`).join('\n');const id=prompt(`${list||'Правил немає.'}\n\nВведіть номер правила для редагування або 0 для нового:`,'0');if(id===null)return;const previous=Number(id)>0?taxRules[Number(id)-1]:null;if(Number(id)>0&&!previous)return alert('Правило не знайдено.');const name=prompt('Назва правила:',previous?.name||'Податок');if(!name)return;const basis=prompt("Основа: income_percent або fixed:",previous?.basis||'income_percent');if(!['income_percent','fixed'].includes(basis))return alert('Некоректна основа.');const value=Number(prompt(basis==='income_percent'?'Відсоток:':'Фіксована сума:',previous?.value||'')),account=prompt('Рахунок:',previous?.account||Object.keys(accounts)[0]),payDay=Math.max(1,Math.min(31,Number(prompt('День сплати наступного місяця:',previous?.payDay||'20'))||1)),next={id:previous?.id||newId(),name,basis,value,account,payDay,active:confirm('Правило активне?')};if(previous)taxRules[taxRules.indexOf(previous)]=next;else taxRules.push(next);log('Змінено правило податку',`${JSON.stringify(previous)} → ${JSON.stringify(next)}`);save();renderPlannedPayments()}
function renderPlannedDashboard(){const today=isoLocal(new Date()),week=addDays(today,7),active=plannedPayments.filter(item=>item.status==='planned'&&!item.isDeleted),balances=Object.fromEntries(Object.keys(accounts).map(account=>[account,balanceFor(account)])),coverage=window.FinbaseAccounting.coverageByMonth(balances,plannedPayments,plannedSettings,today);$('overduePlannedMetric').textContent=active.filter(item=>item.dueDate<today).length;$('weekPlannedMetric').textContent=`₴ ${money(active.filter(item=>item.dueDate>=today&&item.dueDate<=week).reduce((sum,item)=>sum+window.FinbasePlannedPayments.remainingAmount(item),0))}`;$('plannedDeficitMetric').textContent=`₴ ${money(coverage.reduce((sum,item)=>sum+item.deficit,0))}`}
$('newPlannedPayment').onclick=()=>openPlannedPaymentModal();$('createFromTemplates').onclick=createFromTemplates;$('manageTemplates').onclick=manageTemplates;$('manageTaxRules').onclick=manageTaxRules;plannedView.querySelectorAll('[data-planned-mode]').forEach(button=>button.onclick=()=>{plannedViewMode=button.dataset.plannedMode;plannedView.querySelectorAll('[data-planned-mode]').forEach(item=>item.classList.toggle('active',item===button));renderPlannedPayments()});plannedView.querySelector('.planned-filters').onchange=()=>{plannedFilterState={account:$('plannedAccountFilter').value,kind:$('plannedKindFilter').value,status:$('plannedStatusFilter').value,month:$('plannedPeriodFilter').value};renderPlannedPayments();$('plannedAccountFilter').value=plannedFilterState.account;$('plannedKindFilter').value=plannedFilterState.kind};$('plannedPaymentsContent').onclick=e=>{const button=e.target.closest('[data-pay-planned],[data-edit-planned],[data-cancel-planned]');if(!button)return;const id=button.dataset.payPlanned||button.dataset.editPlanned||button.dataset.cancelPlanned,item=plannedPayments.find(row=>String(row.id)===String(id));if(!item)return;if(button.dataset.payPlanned){showSection('transactions');openModal();document.querySelector('input[name="transactionType"][value="expense"]').checked=true;updateForm();$('plannedPaymentId').value=item.id;applyPlannedPaymentSelection();return}if(button.dataset.editPlanned){openPlannedPaymentModal(item);return}const comment=prompt('Коментар до скасування (мінімум 5 символів):','');if(!comment)return;try{window.financePlannedPayments.cancel(item.id,comment);renderPlannedPayments()}catch(error){alert(error.message)}};
const showSectionBeforePlanned=showSection;showSection=function(name){showSectionBeforePlanned(name);plannedView.hidden=name!=='planned';plannedNav.classList.toggle('active',name==='planned');if(name==='planned'){document.querySelectorAll('.transaction-view').forEach(item=>item.hidden=true);['accountsView','reportsView','statisticsView','periodsView','journalView'].forEach(id=>{if($(id))$(id).hidden=true});document.querySelectorAll('.main-nav a').forEach(item=>item.classList.toggle('active',item===plannedNav));renderPlannedPayments()}};plannedNav.onclick=e=>{e.preventDefault();showSection('planned')};window.addEventListener('finbase:show-planned-payments',()=>showSection('planned'));
const renderBeforePlanned=render;render=function(){recalculateTaxState();renderBeforePlanned();renderPlannedDashboard();if(!plannedView.hidden)renderPlannedPayments()};render();
const showSnapshotBeforePlanned=showSnapshot;showSnapshot=function(period){showSnapshotBeforePlanned(period);const snapshot=period?.snapshot;if(!snapshot)return;$('snapshotBody').insertAdjacentHTML('beforeend',`<h3>Планові платежі на дату закриття</h3><p>${Object.entries(snapshot.frozenByAccount||{}).map(([account,value])=>`${escapeHtml(account)}: заморожено ₴ ${money(value)}`).join('<br>')||'Дані відсутні'}</p><p><b>Дефіцит:</b> ₴ ${money(snapshot.plannedDeficit||0)}</p>${(snapshot.plannedPayments||[]).map(item=>`<p>${escapeHtml(item.name)} · ${item.dueDate} · ${escapeHtml(item.account)} · залишок ₴ ${money(item.remaining)}</p>`).join('')}`)};
